<template><div class="searchable-select"><input v-model="query" :placeholder="placeholder" autocomplete="off" @focus="open=true" @input="search"/><div v-if="open" class="searchable-options"><div role="option" tabindex="0" @click="choose('')" @keydown.enter="choose('')">Unassigned</div><div v-for="option in options" :key="option.id" role="option" tabindex="0" @click="choose(option.id)" @keydown.enter="choose(option.id)">{{option.label}}</div><p v-if="!loading&&!options.length">No matching areas</p><small v-if="loading">Searching…</small></div></div></template>
<script setup lang="ts">import{onMounted,onBeforeUnmount,ref,watch}from'vue';import{platformApi}from'@/services/platform';const props=withDefaults(defineProps<{modelValue:string|null;placeholder?:string}>(),{placeholder:'Search mouza, upazila or district'});const emit=defineEmits<{ 'update:modelValue':[value:string] }>();const query=ref(''),options=ref<any[]>([]),open=ref(false),loading=ref(false);let timer:number|undefined=undefined,requestVersion=0;async function load(q=''){const version=++requestVersion;loading.value=true;try{const{data}=await platformApi.areaLookup(q);if(version===requestVersion)options.value=data}catch{if(version===requestVersion)options.value=[]}finally{if(version===requestVersion)loading.value=false}}function search(){if(timer)window.clearTimeout(timer);timer=window.setTimeout(()=>load(query.value),280)}function choose(id:string){emit('update:modelValue',id);const item=options.value.find(x=>x.id===id);query.value=item?.label||'Unassigned';open.value=false}watch(()=>props.modelValue,async id=>{if(!id){query.value='Unassigned';return}if(!options.value.length)await load('');query.value=options.value.find(x=>x.id===id)?.label||''},{immediate:true});onMounted(()=>load(''));onBeforeUnmount(()=>{if(timer)window.clearTimeout(timer)});</script>
